CARDIO.register({"item":"d302","meta":{"num":"d302","label":"302","spe":"dermato","short":"Tumeurs cutanées","title":"Tumeurs cutanées, épithéliales et mélaniques","section":"D","chapter":20,"pages":"351-391","sdd":[{"num":84,"label":"Lésion cutanée/« grain de beauté »"},{"num":90,"label":"Tache cutanée du nourrisson"},{"num":178,"label":"Demande/prescription raisonnée et choix d'un examen diagnostique"},{"num":303,"label":"Prévention/dépistage des cancers de l'adulte"},{"num":327,"label":"Annonce d'un diagnostic de maladie grave au patient et/ou à sa famille"}]},"objectives":[{"id":"d302-obj-01","rank":"A","rubric":"Définition","title":"Connaître les principales tumeurs cutanées","desc":"Lister les grandes familles de tumeurs cutanées (basocellulaire, épidermoïde, mélanome, tumeurs induites par HPV) et leur fréquence"},{"id":"d302-obj-02","rank":"A","rubric":"Diagnostic positif","title":"Connaître la présentation clinique d'une tumeur épithéliale bénigne à HPV","desc":"Savoir diagnostiquer une tumeur épithéliale bénigne à HPV. Connaître la définition, l'épidémiologie et la prise en charge globale des tumeurs épithéliales bénignes à HPV (diagnostic, évolution, diagnostics différentiels, thérapeutique et suivi)"},{"id":"d302-obj-03","rank":"B","rubric":"Prévalence, épidémiologie","title":"Connaître l'épidémiologie des tumeurs cutanées","desc":""},{"id":"d302-obj-04","rank":"A","rubric":"Prise en charge","title":"Connaître les principes de la prise en charge globale des tumeurs cutanées","desc":""},{"id":"d302-obj-05","rank":"A","rubric":"Diagnostic positif","title":"Connaître la présentation clinique et la démarche diagnostique devant un carcinome basocellulaire, épidermoïde","desc":"Connaître les signes cliniques permettant de poser le diagnostic de carcinome basocellulaire et épidermoïde et d'écarter les diagnostics différentiels"},{"id":"d302-obj-06","rank":"B","rubric":"Suivi et/ou pronostic","title":"Connaître le pronostic des carcinomes basocellulaires et épidermoïdes","desc":"Lister les facteurs de risque d'évolution péjorative des cancers épidermoïdes"},{"id":"d302-obj-07","rank":"A","rubric":"Prise en charge","title":"Prévention des carcinomes épidermoïdes et basocellulaires","desc":"Connaître les modalités de prévention des carcinomes épidermoïdes et basocellulaires"},{"id":"d302-obj-08","rank":"A","rubric":"Définition","title":"Connaître la définition et les principaux facteurs de risque des nævus","desc":"Connaître la définition, les facteurs de risque, les différentes formes cliniques et profils évolutifs des nævus"},{"id":"d302-obj-09","rank":"B","rubric":"Diagnostic positif","title":"Nævus : diagnostics différentiels","desc":"Connaître les principaux diagnostics différentiels des nævus à évoquer de principe"},{"id":"d302-obj-10","rank":"B","rubric":"Éléments physiopathologiques","title":"Physiopathologie des nævus","desc":"Retracer l'histoire naturelle du processus de cancérisation dans le cadre du mélanome"},{"id":"d302-obj-11","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes cliniques du mélanome","desc":"Savoir rechercher les cinq caractéristiques (règle ABCDE) orientant vers une tumeur mélanique maligne. Connaître les modalités d'obtention du diagnostic de certitude"},{"id":"d302-obj-12","rank":"B","rubric":"Suivi et/ou pronostic","title":"Évolution et pronostic du mélanome","desc":"Distinguer les différentes entités anatomocliniques des mélanomes et connaître les critères histopronostiques ainsi que leur implication pronostique. Connaître les principaux facteurs cliniques de mauvais pronostic"},{"id":"d302-obj-13","rank":"A","rubric":"Prise en charge","title":"Connaître les modalités de prévention du mélanome","desc":""},{"id":"d302-obj-14","rank":"B","rubric":"Contenu multimédia","title":"Savoir reconnaître une lésion précancéreuse cutanée","desc":"Photographie de kératoses actiniques typiques"},{"id":"d302-obj-15","rank":"B","rubric":"Contenu multimédia","title":"Savoir reconnaître un carcinome basocellulaire","desc":"Photographie d'un carcinome basocellulaire typique"},{"id":"d302-obj-16","rank":"B","rubric":"Contenu multimédia","title":"Savoir reconnaître un carcinome épidermoïde","desc":"Photographie d'un carcinome épidermoïde typique"},{"id":"d302-obj-17","rank":"A","rubric":"Contenu multimédia","title":"Savoir reconnaître un mélanome","desc":"Photographie d'un mélanome typique"}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"d302-qroc-001","type":"QROC","rank":"A","objective":"d302-obj-01","tags":["définition","épidémiologie"],"difficulty":1,"question":"Quel est le cancer cutané (et aussi épithélial) le plus fréquent ?","answer":"Le carcinome basocellulaire (CBC)","accept":["carcinome basocellulaire","CBC","basocellulaire","carcinome baso-cellulaire"],"keywords":["basocell"],"explanation":"Le CBC est le cancer épithélial et cutané le plus fréquent ; il ne siège jamais sur les muqueuses et évolue lentement, de façon purement locale.","src":"p. 365"},{"id":"d302-qroc-002","type":"QROC","rank":"A","objective":"d302-obj-01","tags":["épidémiologie"],"difficulty":1,"question":"Quelle part des cancers cutanés représentent les carcinomes (basocellulaires et épidermoïdes) ?","answer":"Environ 90 %","accept":["90 %","90%","90","90 pour cent"],"keywords":["90"],"explanation":"Les carcinomes cutanés sont les cancers de l'adulte les plus fréquents au monde et forment environ 90 % des cancers cutanés ; leur incidence augmente de façon constante.","src":"p. 355"},{"id":"d302-qroc-003","type":"QROC","rank":"A","objective":"d302-obj-03","tags":["étiologie","physiopathologie"],"difficulty":1,"question":"Quel agent est le principal carcinogène d'initiation de la carcinogenèse épithéliale cutanée ?","answer":"Les rayons ultraviolets (UV)","accept":["UV","ultraviolets","rayons ultraviolets","exposition solaire","soleil"],"keywords":["uv"],"explanation":"L'initiation relève d'agents carcinogènes dont les UV (+++), puis les agents chimiques, les radiations ionisantes, l'inflammation chronique et les HPV.","src":"p. 355"},{"id":"d302-qroc-004","type":"QROC","rank":"A","objective":"d302-obj-03","tags":["étiologie"],"difficulty":2,"question":"Quel profil d'exposition solaire favorise surtout le carcinome épidermoïde ?","answer":"Des expositions chroniques et cumulées","accept":["chronique","cumulée","cumulative","chroniques et cumulées"],"keywords":["chroniq","cumul"],"explanation":"Le CE (comme le CBC) est favorisé par les expositions chroniques et cumulées. Les expositions intenses et intermittentes (coups de soleil, sujet jeune) favorisent le mélanome (et le CBC).","src":"p. 356"},{"id":"d302-qroc-005","type":"QROC","rank":"A","objective":"d302-obj-03","tags":["étiologie"],"difficulty":2,"question":"Quel profil d'exposition solaire favorise surtout le mélanome ?","answer":"Des expositions intenses et intermittentes (coups de soleil)","accept":["intermittentes","intermittente","coups de soleil","intenses et intermittentes"],"keywords":["intermittent"],"explanation":"Le mélanome (comme le CBC) est favorisé par les expositions solaires intenses et intermittentes avec coups de soleil, surtout chez le sujet jeune. Le CE relève plutôt des expositions chroniques et cumulées.","src":"p. 356"},{"id":"d302-qroc-006","type":"QROC","rank":"A","objective":"d302-obj-03","tags":["étiologie"],"difficulty":1,"question":"Quelle situation d'immunosuppression iatrogène expose particulièrement aux cancers cutanés ?","answer":"La transplantation d'organes","accept":["transplantation d'organes","transplantation","greffe d'organe","greffe","transplantés"],"keywords":["transplant"],"explanation":"L'immunosuppression acquise majore le risque de cancers cutanés : transplantation d'organes (+++), hémopathies chroniques (leucémie lymphoïde chronique, lymphome), infection VIH.","src":"p. 356"},{"id":"d302-qroc-007","type":"QROC","rank":"A","objective":"d302-obj-05","tags":["étiologie","clinique"],"difficulty":1,"question":"Quelle est la lésion précancéreuse cutanée la plus fréquente ?","answer":"La kératose actinique (solaire ou sénile)","accept":["kératose actinique","kératoses actiniques","kératose solaire","kératoses solaires","kératose sénile","kératoses séniles"],"keywords":["kératose"],"explanation":"Les kératoses actiniques photo-induites sont très fréquentes mais leur potentiel de transformation est limité ; elles sont surtout un marqueur de risque de cancer cutané.","src":"p. 357"},{"id":"d302-qroc-008","type":"QROC","rank":"A","objective":"d302-obj-05","tags":["clinique"],"difficulty":1,"question":"À quoi compare-t-on classiquement la surface d'une kératose actinique à la palpation ?","answer":"À du papier de verre (rugueuse)","accept":["papier de verre","rugueuse","rugueux"],"keywords":["papier","verre"],"explanation":"Les KA sont des lésions kératosiques ou croûteuses, multiples, parfois érythémateuses, rugueuses « papier de verre », qui saignent facilement après grattage ; elles siègent sur les zones photo-exposées (visage, dos des mains).","src":"p. 357"},{"id":"d302-qroc-009","type":"QROC","rank":"A","objective":"d302-obj-05","tags":["définition","physiopathologie"],"difficulty":2,"question":"Comment nomme-t-on une zone cutanée portant des anomalies prénéoplasiques et des mutations infracliniques multifocales, qui se traduit par des kératoses actiniques multiples ?","answer":"Un champ de cancérisation","accept":["champ de cancérisation","cancérisation de champ"],"keywords":["champ","cancér"],"explanation":"Sur le plan clinique, le champ de cancérisation se manifeste par des kératoses actiniques multiples, parfois associées à un CE ou à un CBC.","src":"p. 357"},{"id":"d302-qroc-010","type":"QROC","rank":"A","objective":"d302-obj-05","tags":["étiologie","clinique"],"difficulty":1,"question":"Quel précurseur muqueux du CE, blanchâtre, adhérent, asymptomatique et ne saignant pas au contact, siège volontiers sur la lèvre inférieure (rôle du tabac et des UV) ?","answer":"La leucoplasie","accept":["leucoplasie","leucoplasies"],"keywords":["leucoplasie"],"explanation":"La leucoplasie correspond à une kératinisation anormale de la muqueuse : lésions blanchâtres bien limitées, asymptomatiques, adhérentes, qui ne saignent pas au contact.","src":"p. 357"},{"id":"d302-qroc-011","type":"QROC","rank":"A","objective":"d302-obj-05","tags":["définition","clinique"],"difficulty":1,"question":"Comment appelle-t-on la forme non invasive du carcinome épidermoïde (dysplasie de toute la hauteur de l'épithélium, membrane basale respectée), le plus souvent une plaque érythémateuse squamo-croûteuse bien limitée en zone photo-exposée ?","answer":"Le carcinome in situ (maladie de Bowen)","accept":["maladie de Bowen","Bowen","carcinome in situ","carcinome intra-épithélial","carcinome intraépithélial"],"keywords":["bowen"],"explanation":"Le carcinome in situ ne franchit pas la membrane basale : la métastase est impossible. La biopsie avec examen anatomopathologique confirme le diagnostic.","src":"p. 357-358"},{"id":"d302-qroc-012","type":"QROC","rank":"A","objective":"d302-obj-05","tags":["clinique"],"difficulty":1,"question":"Comment nomme-t-on le carcinome in situ du gland, qui forme une lésion rouge vif, bien limitée, parfois discrètement érosive ?","answer":"L'érythroplasie de Queyrat","accept":["érythroplasie de Queyrat","Queyrat"],"keywords":["queyrat"],"explanation":"C'est la forme du sujet masculin ; chez la femme, la lésion est unique, chronique, plane ou peu infiltrée, rosée avec des plages pigmentées. La biopsie confirme le diagnostic.","src":"p. 358"},{"id":"d302-qroc-013","type":"QROC","rank":"A","objective":"d302-obj-05","tags":["clinique","complications"],"difficulty":2,"question":"Quels signes, sur un carcinome in situ, font craindre une lésion invasive à potentiel métastatique ?","answer":"Une infiltration et/ou une ulcération franche","accept":["infiltration","ulcération","ulcération franche"],"keywords":["infiltr","ulcér"],"explanation":"Une infiltration, avec ou sans ulcération franche, fait évoquer une lésion invasive, qui aura alors un potentiel métastatique.","src":"p. 358"},{"id":"d302-qroc-014","type":"QROC","rank":"A","objective":"d302-obj-05","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quelles sont les trois clés sémiologiques du carcinome épidermoïde cutané invasif ?","answer":"Ulcération chronique, bourgeonnement, croûte","accept":["ulcération, bourgeonnement, croûte","ulcération chronique, bourgeonnement, croûte"],"keywords":["ulcér","bourgeon","croûte"],"explanation":"Le CEC invasif apparaît surtout après 60 ans (homme plus souvent que femme), sur une zone chroniquement photo-exposée : lésion ulcérée et/ou bourgeonnante (végétante), croûteuse, jaunâtre, indurée. Aspect évocateur : biopsie ou exérèse pour examen anatomopathologique.","src":"p. 358-359"},{"id":"d302-qroc-015","type":"QROC","rank":"A","objective":"d302-obj-05","tags":["paraclinique","diagnostic"],"difficulty":2,"question":"Devant un carcinome épidermoïde cutané, dans quelles situations réalise-t-on un bilan d'extension (échographie ganglionnaire, scanner, TEP) ?","answer":"Forme agressive, immunodépression ou signe d'extension locorégionale","accept":[],"keywords":["agressi","immuno","extension"],"explanation":"Il n'y a pas de bilan d'extension systématique : il est réservé aux formes agressives, au terrain à risque particulier (immunodéprimé) ou aux signes cliniques d'extension locorégionale (échographie ganglionnaire, scanner thoraco-abdominal, TEP-scan).","src":"p. 360"},{"id":"d302-qroc-016","type":"QROC","rank":"A","objective":"d302-obj-05","tags":["étiologie","pièges"],"difficulty":2,"question":"Quelle lésion précancéreuse précède habituellement un carcinome basocellulaire ?","answer":"Aucune : le CBC n'a pas de précurseur","accept":["aucune","aucun","pas de précurseur","pas de lésion précancéreuse","sans précurseur"],"keywords":["aucun"],"explanation":"Le CBC ne survient pas sur une lésion précancéreuse : les kératoses actiniques ne se transforment pas en CBC. Le CE, lui, naît souvent d'un précurseur (continuum précurseur, carcinome in situ, carcinome invasif).","src":"p. 361, 365"},{"id":"d302-qroc-017","type":"QROC","rank":"A","objective":"d302-obj-05","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quelle lésion élémentaire quasi constante est la clé sémiologique du carcinome basocellulaire ?","answer":"La perle (papule rosée, translucide, télangiectasique)","accept":["perle","lésion perlée","papule perlée","aspect perlé"],"keywords":["perl"],"explanation":"La perle est une papule rosée arrondie, translucide, souvent parcourue de télangiectasies, de taille variable ; elle s'associe parfois à des croûtes, une sclérose, une ulcération, une pigmentation ou une kératose.","src":"p. 361"},{"id":"d302-qroc-018","type":"QROC","rank":"A","objective":"d302-obj-05","tags":["clinique"],"difficulty":1,"question":"Quelles sont les trois formes cliniques de carcinome basocellulaire ?","answer":"Nodulaire (la plus fréquente), superficiel, sclérodermiforme","accept":[],"keywords":["nodulaire","superficiel","sclérodermiforme"],"explanation":"Nodulaire : tumeur ferme, lisse, bien limitée. Superficiel : plaque érythémateuse et squameuse, surtout du tronc, bordée de petites perles. Sclérodermiforme : cicatrice blanchâtre, dure, mal limitée. Toutes peuvent s'ulcérer.","src":"p. 361"},{"id":"d302-qroc-019","type":"QROC","rank":"A","objective":"d302-obj-05","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quel diagnostic grave faut-il éliminer devant un CBC pigmenté (« CBC tatoué ») ?","answer":"Un mélanome","accept":["mélanome","un mélanome"],"keywords":["mélanome"],"explanation":"Les diagnostics différentiels du CBC sont les autres tumeurs cutanées (CEC, maladie de Bowen, mélanome pour les formes pigmentées) et, pour le CBC superficiel, le psoriasis ou une dermatophytie. Aspect évocateur : exérèse diagnostique et examen anatomopathologique.","src":"p. 363"},{"id":"d302-qroc-020","type":"QROC","rank":"A","objective":"d302-obj-04","tags":["traitement"],"difficulty":1,"question":"Quel est le traitement de première intention des carcinomes cutanés localisés (CBC et CE) ?","answer":"L'exérèse chirurgicale avec marges de sécurité","accept":["exérèse chirurgicale","chirurgie","exérèse","exérèse chirurgicale avec marge"],"keywords":["exérèse"],"explanation":"Le traitement des formes localisées de CBC et de CE est généralement similaire : exérèse avec marges adaptées au groupe pronostique (bon, intermédiaire, mauvais), discutée en RCP sauf pour les CBC sans critère agressif.","src":"p. 363-364"},{"id":"d302-qroc-021","type":"QROC","rank":"A","objective":"d302-obj-04","tags":["traitement"],"difficulty":2,"question":"Entre quelles valeurs se situent les marges d'exérèse standardisées d'un carcinome cutané ?","answer":"De 3 à 10 mm (plus larges pour le CE que pour le CBC)","accept":["3 à 10 mm","3-10 mm","entre 3 et 10 mm","3 et 10 mm","3 à 10"],"keywords":["3","10"],"explanation":"La marge saine, mesurée autour de la tumeur, varie de 3 à 10 mm selon le type de tumeur et son groupe pronostique ; elle est plus élevée pour le CEC que pour le CBC.","src":"p. 364"},{"id":"d302-qroc-022","type":"QROC","rank":"A","objective":"d302-obj-04","tags":["traitement","pièges"],"difficulty":1,"question":"Que faut-il faire si l'exérèse chirurgicale d'un carcinome est incomplète ou « limite » à l'examen anatomopathologique ?","answer":"Une reprise chirurgicale est indispensable","accept":["reprise","reprise chirurgicale","reprise indispensable","nouvelle exérèse","réintervention","reprise des marges"],"keywords":["reprise"],"explanation":"Le contrôle anatomopathologique de la pièce juge du caractère complet de l'exérèse ; si elle est incomplète ou « limite », la reprise est indispensable.","src":"p. 364"},{"id":"d302-qroc-023","type":"QROC","rank":"A","objective":"d302-obj-04","tags":["suivi"],"difficulty":2,"question":"Que dépiste la surveillance médicale régulière après le traitement d'un carcinome cutané ?","answer":"Récidive locale ou ganglionnaire, nouveau carcinome, mélanome","accept":["récidive, nouveau carcinome, mélanome","récidive locale ou ganglionnaire, nouveau carcinome, mélanome"],"keywords":["récidive","nouveau","mélanome"],"explanation":"Le suivi clinique est régulier selon le groupe pronostique et les facteurs de risque, au mieux à vie ; le patient est aussi éduqué à l'autosurveillance et à l'autodépistage.","src":"p. 364, 366"},{"id":"d302-qroc-024","type":"QROC","rank":"A","objective":"d302-obj-07","tags":["prévention"],"difficulty":1,"question":"Entre quelles heures faut-il éviter de s'exposer au soleil ?","answer":"Entre 12 h et 16 h","accept":["12 h et 16 h","12h et 16h","12 heures et 16 heures","12h-16h","12 à 16 h","entre 12 et 16"],"keywords":["12","16"],"explanation":"Prévention solaire : éviter les expositions entre 12 h et 16 h, se protéger (chapeau, vêtements, ombre), limiter l'exposition surtout pendant l'enfance et l'adolescence, déconseiller les lampes à bronzer.","src":"p. 365"},{"id":"d302-qroc-025","type":"QROC","rank":"A","objective":"d302-obj-07","tags":["prévention","pièges"],"difficulty":2,"question":"Quelle règle d'utilisation s'applique à l'écran solaire dans la prévention des cancers cutanés ?","answer":"Il ne doit pas permettre d'allonger le temps d'exposition","accept":["ne pas allonger le temps d'exposition","ne pas augmenter le temps d'exposition","ne doit pas augmenter le temps d'exposition","ne doit pas permettre d'augmenter le temps d'exposition"],"keywords":["exposition"],"explanation":"L'écran solaire est utile ponctuellement pour éviter un coup de soleil, mais il ne doit pas autoriser à prolonger l'exposition solaire.","src":"p. 365"},{"id":"d302-qroc-026","type":"QROC","rank":"B","objective":"d302-obj-06","tags":["complications"],"difficulty":2,"question":"Quelles localisations d'un carcinome épidermoïde cutané sont considérées à haut risque de mauvais pronostic ?","answer":"Cuir chevelu, zones péri-orificielles du visage, muqueuses, peau pathologique","accept":[],"keywords":["cuir chevelu","orificiel","muqueuse"],"explanation":"Les zones péri-orificielles du visage sont le nez, les lèvres, les oreilles et les paupières ; la peau pathologique comprend radiodermites, cicatrices de brûlures et plaies chroniques. Les zones photo-exposées du visage (hors cuir chevelu et péri-orificielles), le tronc et les membres sont à faible risque.","src":"p. 360"},{"id":"d302-qroc-027","type":"QROC","rank":"B","objective":"d302-obj-06","tags":["complications"],"difficulty":2,"question":"Au-delà de quel diamètre la taille d'un carcinome épidermoïde cutané devient-elle surtout un facteur de mauvais pronostic ?","answer":"Plus de 2 cm","accept":["2 cm","plus de 2 cm","supérieure à 2 cm"],"keywords":["2"],"explanation":"Autres facteurs de mauvais pronostic : invasion locale (adhérence au plan profond, envahissement péri-nerveux ou osseux, emboles vasculaires), différenciation moyenne à indifférenciée, récidive locale, immunodépression.","src":"p. 360"},{"id":"d302-qroc-028","type":"QROC","rank":"A","objective":"d302-obj-02","tags":["clinique"],"difficulty":1,"question":"Quelle verrue plantaire, la plus fréquente, est profonde, douloureuse à la pression et cernée d'un anneau kératosique piqueté de points noirs ?","answer":"La myrmécie (HPV1)","accept":["myrmécie","HPV1","HPV 1"],"keywords":["myrm"],"explanation":"Les points noirs correspondent à des microhémorragies. L'autre variété, moins fréquente, est la verrue en mosaïque (HPV2), non douloureuse, faite de verrues coalescentes en placard kératosique.","src":"p. 368"},{"id":"d302-qroc-029","type":"QROC","rank":"A","objective":"d302-obj-02","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quel diagnostic faut-il évoquer devant une verrue péri- ou sous-unguéale qui persiste ?","answer":"Un carcinome in situ (maladie de Bowen)","accept":["carcinome in situ","Bowen","maladie de Bowen","carcinome épidermoïde in situ","carcinome intra-épithélial"],"keywords":["situ"],"explanation":"Une verrue péri- ou sous-unguéale persistante est à distinguer d'un carcinome in situ. Ces verrues peuvent aussi altérer l'ongle, ce qui constitue une indication de traitement.","src":"p. 369-370"},{"id":"d302-qroc-030","type":"QROC","rank":"A","objective":"d302-obj-02","tags":["diagnostic","pièges"],"difficulty":2,"question":"Parmi les diagnostics différentiels d'une verrue plantaire, quelle tumeur maligne de la plante du pied ne faut-il pas manquer ?","answer":"Un mélanome achromique","accept":["mélanome achromique","mélanome"],"keywords":["mélanome"],"explanation":"Les diagnostics différentiels de la verrue plantaire comprennent le durillon (épaississement lié à un frottement chronique) et, surtout à ne pas manquer, le mélanome achromique de la plante des pieds (+++).","src":"p. 370"},{"id":"d302-qroc-031","type":"QROC","rank":"A","objective":"d302-obj-02","tags":["traitement","suivi"],"difficulty":1,"question":"Quel est le risque de récidive après traitement d'une verrue, lié à la persistance de l'HPV dans la peau saine ?","answer":"Environ 30 %","accept":["30 %","30%","30","environ 30 %","30 pour cent"],"keywords":["30"],"explanation":"Le patient doit être informé de ce risque de récidive. Les verrues régressent le plus souvent spontanément : pas d'acharnement thérapeutique, traitement guidé par les symptômes et le vécu de la maladie.","src":"p. 370"},{"id":"d302-qroc-032","type":"QROC","rank":"A","objective":"d302-obj-02","tags":["traitement"],"difficulty":1,"question":"Quelle préparation kératolytique est utilisée pour détruire chimiquement une verrue ?","answer":"L'acide salicylique (collodion salicylé)","accept":["acide salicylique","salicylique","collodion salicylé","salicylé"],"keywords":["salicyl"],"explanation":"Traitement simple et non douloureux, avec protection de la peau saine autour ; il exige un décapage mécanique superficiel préalable et une application régulière (par exemple chaque soir), suffisamment prolongée.","src":"p. 370-371"},{"id":"d302-qroc-033","type":"QROC","rank":"A","objective":"d302-obj-11","tags":["définition"],"difficulty":1,"question":"Un mélanome est une tumeur maligne développée aux dépens de quelles cellules ?","answer":"Les mélanocytes","accept":["mélanocytes","mélanocyte","cellules qui fabriquent la mélanine"],"keywords":["mélanocyt"],"explanation":"Les mélanocytes sont les cellules qui fabriquent la mélanine.","src":"p. 371"},{"id":"d302-qroc-034","type":"QROC","rank":"A","objective":"d302-obj-11","tags":["clinique","diagnostic"],"difficulty":1,"question":"Que signifient les lettres de la règle ABCDE qui oriente vers un mélanome ?","answer":"Asymétrie, Bords irréguliers, Couleur inhomogène, Diamètre, Évolution","accept":[],"keywords":["asymétrie","bords","évolution"],"explanation":"D = diamètre supérieur à 6 mm (critère non spécifique) ; E = évolution récente documentée (taille, forme, couleur, relief). Cette règle, conçue pour l'éducation du patient à l'autodépistage, est peu efficace pour les modifications subtiles ou récentes.","src":"p. 374"},{"id":"d302-qroc-035","type":"QROC","rank":"A","objective":"d302-obj-11","tags":["clinique","diagnostic"],"difficulty":1,"question":"À partir de combien de critères ABCDE suspecte-t-on un mélanome ?","answer":"Au moins 2 critères","accept":["au moins 2","au moins deux","deux critères ou plus","2 critères ou plus"],"keywords":["2"],"explanation":"La suspicion repose sur au moins 2 critères parmi A, B, C, D, E ; la règle du « vilain petit canard » complète cette approche analytique.","src":"p. 374"},{"id":"d302-qroc-036","type":"QROC","rank":"A","objective":"d302-obj-17","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quelle règle « cognitive » repose sur l'aspect discordant d'un nævus par rapport aux autres nævus du même patient ?","answer":"La règle du « vilain petit canard »","accept":["vilain petit canard","règle du vilain petit canard"],"keywords":["vilain","canard"],"explanation":"Chez un patient donné, les nævus se ressemblent globalement : un nævus discordant fait suspecter un mélanome. Cette règle exige un examen corps entier, patient dénudé.","src":"p. 374"},{"id":"d302-qroc-037","type":"QROC","rank":"A","objective":"d302-obj-11","tags":["diagnostic","traitement"],"difficulty":1,"question":"Quelle est la conduite devant une lésion pigmentée suspecte de mélanome ?","answer":"Exérèse complète rapide à visée diagnostique, puis anatomopathologie","accept":["exérèse complète","exérèse diagnostique","exérèse à visée diagnostique","exérèse"],"keywords":["exérèse"],"explanation":"Sous anesthésie locale, la tumeur est emportée en entier jusqu'à l'hypoderme. L'examen anatomopathologique confirme le diagnostic, précise le sous-type et recueille les critères histopronostiques.","src":"p. 374-375"},{"id":"d302-qroc-038","type":"QROC","rank":"A","objective":"d302-obj-11","tags":["diagnostic","pièges"],"difficulty":2,"question":"Pourquoi ne fait-on pas de biopsie partielle devant un mélanome suspect ?","answer":"Breslow et index mitotique ne sont pas mesurables sur un fragment","accept":["breslow","perte de chance","index mitotique"],"keywords":["breslow","mitotique"],"explanation":"L'épaisseur maximale (Breslow) et l'index mitotique se mesurent sur la pièce entière ; un prélèvement partiel entraîne une perte de chance. Exception : lésion très étendue dont l'exérèse totale serait délabrante (visage), avec biopsie(s) des zones les plus suspectes, après avis d'un centre expert.","src":"p. 374"},{"id":"d302-qroc-039","type":"QROC","rank":"A","objective":"d302-obj-11","tags":["paraclinique","diagnostic"],"difficulty":2,"question":"Quels sont les trois paramètres histopronostiques fondamentaux que précise l'examen anatomopathologique d'un mélanome ?","answer":"Indice de Breslow, ulcération, index mitotique","accept":[],"keywords":["breslow","ulcération","mitotique"],"explanation":"L'examen histologique affirme aussi la nature mélanocytaire (melan-A, protéine S100, HMB45), la malignité, le sous-type anatomoclinique et le caractère complet ou non de l'exérèse.","src":"p. 375"},{"id":"d302-qroc-040","type":"QROC","rank":"B","objective":"d302-obj-12","tags":["complications"],"difficulty":1,"question":"Quel est le principal facteur pronostique d'un mélanome au stade de tumeur primitive ?","answer":"L'indice de Breslow (épaisseur tumorale maximale)","accept":["breslow","indice de breslow","épaisseur tumorale","épaisseur"],"keywords":["breslow"],"explanation":"L'indice de Breslow est corrélé de façon presque linéaire à la mortalité ; l'ulcération a une valeur péjorative importante quelle que soit l'épaisseur.","src":"p. 378"},{"id":"d302-qroc-041","type":"QROC","rank":"B","objective":"d302-obj-12","tags":["diagnostic"],"difficulty":1,"question":"Quel est le type anatomoclinique de mélanome le plus fréquent ?","answer":"Le mélanome superficiel extensif (SSM)","accept":["superficiel extensif","SSM","mélanome superficiel extensif","superficial spreading melanoma"],"keywords":["superficiel"],"explanation":"Le SSM représente 60 à 70 % des mélanomes : croissance horizontale intra-épidermique puis verticale dermique. Il est favorisé par les expositions intermittentes et intenses et les brûlures solaires, surtout dans l'enfance.","src":"p. 372, 375"},{"id":"d302-qroc-042","type":"QROC","rank":"B","objective":"d302-obj-12","tags":["diagnostic"],"difficulty":2,"question":"Quel mélanome siège sur le visage de sujets de plus de 60 ans, avec signes de photovieillissement et longue phase horizontale avant de s'invasiver ?","answer":"Le mélanome de Dubreuilh","accept":["Dubreuilh","mélanome de Dubreuilh"],"keywords":["dubreuilh"],"explanation":"Il est lié à l'exposition chronique cumulative ; il peut devenir invasif sous forme de nodules à croissance verticale.","src":"p. 372, 375"},{"id":"d302-qroc-043","type":"QROC","rank":"B","objective":"d302-obj-12","tags":["diagnostic"],"difficulty":2,"question":"Quel type de mélanome prédomine chez les sujets à peau pigmentée et siège aux paumes, plantes, bords latéraux des doigts et appareil unguéal ?","answer":"Le mélanome acral lentigineux (ALM)","accept":["acral lentigineux","ALM","mélanome acral","acral"],"keywords":["acral"],"explanation":"Il représente 2 à 5 % des cas, mais la majorité chez les sujets à peau pigmentée ; les mélanomes des paumes, des plantes et des muqueuses n'ont pas de lien avec les expositions solaires.","src":"p. 372, 375"},{"id":"d302-qroc-044","type":"QROC","rank":"A","objective":"d302-obj-04","tags":["traitement"],"difficulty":1,"question":"Quel est le traitement de la tumeur primitive d'un mélanome après l'exérèse diagnostique ?","answer":"Exérèse élargie complémentaire jusqu'au fascia, marges selon le Breslow","accept":["exérèse élargie","reprise élargie","reprise chirurgicale élargie","exérèse chirurgicale élargie","reprise des marges"],"keywords":["élargie","breslow"],"explanation":"Une exérèse élargie complémentaire emporte toute l'épaisseur cutanée jusqu'au fascia (en le respectant), avec des marges qui dépendent surtout de l'indice de Breslow.","src":"p. 380"},{"id":"d302-qroc-045","type":"QROC","rank":"A","objective":"d302-obj-04","tags":["traitement"],"difficulty":1,"question":"Quelle marge chirurgicale est conseillée pour un mélanome intra-épidermique (in situ) ?","answer":"0,5 cm","accept":["0,5 cm","0.5 cm","5 mm","0,5"],"keywords":["0,5"],"explanation":"Marges conseillées (recommandations 2016) : in situ 0,5 cm ; Breslow 0,1 à 1 mm : 1 cm ; 1,1 à 2 mm : 1 à 2 cm ; supérieur à 2 mm : 2 cm.","src":"p. 380"},{"id":"d302-qroc-046","type":"QROC","rank":"A","objective":"d302-obj-04","tags":["traitement"],"difficulty":2,"question":"Quelle marge chirurgicale est conseillée pour un mélanome d'indice de Breslow compris entre 0,1 et 1 mm ?","answer":"1 cm","accept":["1 cm","1cm","10 mm"],"keywords":["1 cm"],"explanation":"À comparer : in situ 0,5 cm ; Breslow 1,1 à 2 mm : 1 à 2 cm ; supérieur à 2 mm : 2 cm.","src":"p. 380"},{"id":"d302-qroc-047","type":"QROC","rank":"A","objective":"d302-obj-04","tags":["traitement"],"difficulty":1,"question":"Quelle marge chirurgicale est conseillée pour un mélanome d'indice de Breslow supérieur à 2 mm ?","answer":"2 cm","accept":["2 cm","2cm","20 mm"],"keywords":["2 cm"],"explanation":"La profondeur de l'exérèse va jusqu'au fascia, en le respectant. Pour un mélanome de Dubreuilh intra-épidermique, on recommande 1 cm ou un contrôle exhaustif des berges (chirurgie de Mohs).","src":"p. 380"},{"id":"d302-qroc-048","type":"QROC","rank":"A","objective":"d302-obj-04","tags":["traitement","pièges"],"difficulty":1,"question":"Quelle est la place de la radiothérapie et de la chimiothérapie dans le traitement d'un mélanome au stade de tumeur primitive isolée ?","answer":"Elles ne sont jamais indiquées","accept":["jamais","jamais indiquées","aucune","pas indiquées","non indiquées"],"keywords":["jamais"],"explanation":"Au stade de tumeur primitive isolée, le traitement est chirurgical : exérèse élargie avec marges selon le Breslow.","src":"p. 380"},{"id":"d302-qroc-049","type":"QROC","rank":"A","objective":"d302-obj-13","tags":["prévention","suivi"],"difficulty":2,"question":"Quels sujets sont à très haut risque de mélanome et relèvent d'un suivi dermatologique spécifique (photographies, vidéodermoscopie) ?","answer":"Antécédent de premier mélanome et syndrome des nævus atypiques","accept":[],"keywords":["antécédent","atypique"],"explanation":"La prévention secondaire vise le dépistage précoce : le médecin examine tout le tégument, repère les lésions suspectes (ABCDE, vilain petit canard), adresse à un expert en cas de doute et préfère une exérèse diagnostique au doute.","src":"p. 382"},{"id":"d302-qroc-050","type":"QROC","rank":"A","objective":"d302-obj-08","tags":["définition"],"difficulty":1,"question":"Comment définit-on un nævus mélanocytaire ?","answer":"Prolifération ou accumulation de mélanocytes normaux en situation anormale","accept":[],"keywords":["mélanocytes","anormale"],"explanation":"Le terme « nævus » sans adjectif désigne en général un nævus mélanocytaire. Les cellules sont regroupées en thèques (amas), ce qui aide à distinguer un nævus d'un mélanome.","src":"p. 383-384"},{"id":"d302-qroc-051","type":"QROC","rank":"A","objective":"d302-obj-08","tags":["physiopathologie"],"difficulty":2,"question":"Comment appelle-t-on le nævus dont les thèques mélanocytaires sont à la fois dans le derme et à la jonction dermo-épidermique ?","answer":"Le nævus mixte (ou composé)","accept":["mixte","composé","nævus mixte","nævus composé","nevus mixte"],"keywords":["mixte"],"explanation":"Nævus jonctionnel : thèques dans la couche basale de l'épiderme ; nævus dermique : thèques strictement intradermiques ; nævus mixte (composé) : les deux. La composante jonctionnelle, marquée chez l'enfant, diminue avec l'âge.","src":"p. 383"},{"id":"d302-qroc-052","type":"QROC","rank":"A","objective":"d302-obj-08","tags":["grossesse","pièges"],"difficulty":2,"question":"Chez une femme enceinte, quelle conduite adopter devant un nævus modifié (taille, pigmentation) qui fait douter ?","answer":"Réaliser une exérèse","accept":["exérèse","exérèse chirurgicale","excision"],"keywords":["exérèse"],"explanation":"La grossesse peut augmenter la taille des nævus (abdomen ++) et modifier leur pigmentation ; la vigilance s'impose car des formes agressives de mélanome sont possibles (immuno-modulation et tolérance accrue liées à la grossesse).","src":"p. 384"},{"id":"d302-qroc-053","type":"QROC","rank":"A","objective":"d302-obj-08","tags":["clinique","pièges"],"difficulty":2,"question":"Devant une mélanonychie, quels éléments font craindre un mélanome ?","answer":"Une évolutivité et l'atteinte d'un seul doigt (monodactylie)","accept":[],"keywords":["évolut","monodactylie"],"explanation":"Un nævus du lit de l'ongle donne une bande homogène, régulière et stable dans le temps. Des mélanonychies multiples chez un sujet à peau foncée, ou sur des ongles soumis à frottement, sont de simples dépôts de pigment.","src":"p. 386"},{"id":"d302-qroc-054","type":"QROC","rank":"A","objective":"d302-obj-08","tags":["définition","pédiatrie"],"difficulty":1,"question":"Quel diamètre projeté à l'âge adulte définit un nævus congénital « de grande taille » ?","answer":"Plus de 20 cm","accept":["20 cm","plus de 20 cm","supérieur à 20 cm","supérieure à 20 cm"],"keywords":["20"],"explanation":"Les nævus congénitaux concernent moins de 1 % des naissances ; ceux de grande taille sont rares, avec un impact esthétique et un risque accru de mélanome.","src":"p. 386"},{"id":"d302-qroc-055","type":"QROC","rank":"A","objective":"d302-obj-08","tags":["clinique","pédiatrie"],"difficulty":1,"question":"Quelle tache ardoisée lombo-sacrée du nourrisson, très fréquente chez les enfants d'origine africaine ou asiatique, disparaît le plus souvent pendant l'enfance ?","answer":"La tache bleue mongolique","accept":["tache bleue mongolique","tache mongolique","mongolique"],"keywords":["mongolique"],"explanation":"Elle s'apparente à un nævus bleu congénital : tache d'environ 10 cm de diamètre, présente aussi chez 1 % des enfants à peau claire.","src":"p. 387"},{"id":"d302-qroc-056","type":"QROC","rank":"A","objective":"d302-obj-08","tags":["clinique"],"difficulty":1,"question":"Comment nomme-t-on le halo achromique qui se développe autour d'un nævus pigmenté et aboutit à sa disparition ?","answer":"Le halo nævus (phénomène de Sutton)","accept":["halo nævus","halo naevus","halo nevus","phénomène de Sutton","Sutton","nævus de Sutton"],"keywords":["halo"],"explanation":"Il est lié à un infiltrat inflammatoire cytotoxique et survient surtout vers la deuxième décennie, sur le tronc ; une survenue plus tardive ou un halo irrégulier doivent faire craindre un mélanome.","src":"p. 387"},{"id":"d302-qroc-057","type":"QROC","rank":"A","objective":"d302-obj-08","tags":["étiologie"],"difficulty":1,"question":"À partir de combien de nævus communs parle-t-on de « grand nombre », marqueur de risque de mélanome ?","answer":"Plus de 50 nævus","accept":["50","plus de 50","plus de 50 nævus","supérieur à 50"],"keywords":["50"],"explanation":"Autres marqueurs de risque : nævus de grande taille (supérieur à 5 mm), nævus cliniquement atypiques (plus de 10), antécédents familiaux de mélanome. Les nævus partagent les facteurs de risque du mélanome (phototype clair, exposition solaire).","src":"p. 388"},{"id":"d302-qroc-058","type":"QROC","rank":"A","objective":"d302-obj-13","tags":["suivi"],"difficulty":2,"question":"Quelle est la fréquence minimale de la surveillance médicale des sujets à risque de mélanome ?","answer":"Au moins annuelle, à vie, couplée à l'autosurveillance","accept":["au moins annuelle","annuelle","une fois par an","1 fois par an","tous les ans"],"keywords":["vie"],"explanation":"Une surveillance photographique, dermoscopique ou par calques peut aider à repérer un mélanome parmi plusieurs nævus souvent atypiques.","src":"p. 391"},{"id":"d302-qroc-059","type":"QROC","rank":"B","objective":"d302-obj-09","tags":["diagnostic"],"difficulty":1,"question":"Quelle lésion pigmentée bénigne, la plus fréquente après 40 ans, a une surface rugueuse « grasse » ou « cérébriforme » et des bords rectilignes ?","answer":"La kératose séborrhéique","accept":["kératose séborrhéique","kératoses séborrhéiques"],"keywords":["séborrh"],"explanation":"C'est une prolifération épidermique bénigne ; la dermoscopie aide à la distinguer d'un nævus. Au moindre doute, exérèse pour examen histologique.","src":"p. 389"},{"id":"d302-qroc-060","type":"QROC","rank":"A","objective":"d302-obj-03","tags":["étiologie","clinique"],"difficulty":2,"question":"Dans la classification de Fitzpatrick, que dit-on du bronzage et des coups de soleil d'un sujet de phototype I ?","answer":"Pas de bronzage ; coups de soleil systématiques","accept":["pas de bronzage","ne bronze pas","jamais de bronzage","bronzage nul","coups de soleil systématiques"],"keywords":["bronz","systématique"],"explanation":"Phototype I : carnation très claire, yeux clairs, cheveux blonds ou roux, nombreuses éphélides. Phototype II : bronzage plus ou moins difficile, coups de soleil fréquents. Les carnations claires (I et II) exposent à un risque accru de cancers cutanés.","src":"p. 354, 356"},{"id":"d302-qcm-101","type":"QRM","rank":"A","objective":"d302-obj-03","tags":["étiologie"],"difficulty":2,"stem":"Parmi les facteurs suivants, lesquels augmentent le risque de carcinome cutané ?","options":[{"t":"Un jeune âge","ok":false,"why":"C'est l'âge avancé qui est un facteur de risque commun à la carcinogenèse épithéliale."},{"t":"Un xeroderma pigmentosum","ok":true,"why":"Affection génétique par anomalie des gènes de réparation de l'ADN, qui prédispose aux cancers cutanés."},{"t":"Un phototype cutané foncé (V ou VI)","ok":false,"why":"Le risque est accru chez les sujets à carnation claire (phototypes I et II) : la susceptibilité aux UV est plus forte chez les phototypes clairs que chez les phototypes foncés."},{"t":"Une transplantation d'organe","ok":true,"why":"L'immunosuppression acquise, notamment iatrogène après transplantation d'organes (+++), est un facteur de risque identifié."},{"t":"Une radiodermite chronique","ok":true,"why":"Les radiations ionisantes (radiodermite chronique) font partie des autres facteurs de risque identifiés."}],"explanation":"Facteurs de risque communs : âge avancé, expositions solaires, carnation claire (phototypes I et II). Autres : affections génétiques (xeroderma pigmentosum, épidermodysplasie verruciforme, syndrome de Gorlin), immunosuppression acquise, HPV, radiations ionisantes, dermatoses inflammatoires, plaies chroniques, carcinogènes chimiques.","src":"p. 353, 355-356"},{"id":"d302-qcm-102","type":"QRM","rank":"A","objective":"d302-obj-03","tags":["étiologie","physiopathologie"],"difficulty":2,"stem":"À propos de l'exposition solaire et des cancers cutanés, quelles propositions sont exactes ?","options":[{"t":"Un patient atteint de CBC n'a pas de sur-risque de développer un mélanome ou un autre cancer cutané","ok":false,"why":"Terrain et facteurs de risque sont communs aux CBC, aux CE et aux mélanomes, qui sont souvent associés."},{"t":"Les expositions intenses et intermittentes favorisent surtout le mélanome et le CBC","ok":true,"why":"C'est le profil d'exposition associé au mélanome (et au CBC), notamment chez le sujet jeune."},{"t":"Le cancer cutané apparaît quelques mois seulement après l'exposition aux UV","ok":false,"why":"L'expression clinique est retardée, avec une latence de 30 à 40 ans."},{"t":"Les UV sont le principal agent carcinogène d'initiation","ok":true,"why":"Dans la carcinogenèse épithéliale, l'initiation fait intervenir surtout les UV (+++), puis d'autres agents (chimiques, radiations ionisantes, HPV)."},{"t":"Les expositions chroniques et cumulées favorisent surtout les CE et les CBC","ok":true,"why":"C'est le profil d'exposition associé aux CE et aux CBC (encadré 20.1)."}],"explanation":"UV = agent carcinogène principal ; CE et CBC : expositions chroniques et cumulées ; mélanome et CBC : expositions intenses et intermittentes (coups de soleil) ; latence de 30 à 40 ans.","src":"p. 355-356"},{"id":"d302-qcm-103","type":"QRM","rank":"A","objective":"d302-obj-05","tags":["étiologie","clinique"],"difficulty":2,"stem":"À propos des kératoses actiniques, quelles propositions sont exactes ?","options":[{"t":"Elles se transforment fréquemment en carcinome basocellulaire invasif","ok":false,"why":"Le CBC n'a pas de précurseur : les kératoses actiniques ne se transforment pas en CBC. Elles sont un précurseur du carcinome épidermoïde."},{"t":"Ce sont les lésions précancéreuses cutanées les plus fréquentes","ok":true,"why":"Elles sont très fréquentes, mais leur potentiel de transformation est limité."},{"t":"Leur surface est lisse et brillante, sans caractère kératosique à la palpation","ok":false,"why":"Elles sont rugueuses (« papier de verre ») et saignent facilement après grattage."},{"t":"Elles n'ont aucun potentiel de transformation maligne","ok":false,"why":"Leur potentiel de transformation est limité mais réel : elles sont un marqueur de risque de cancer cutané."},{"t":"Elles siègent surtout sur les zones photo-exposées (visage, dos des mains)","ok":true,"why":"Ce sont des lésions photo-induites des zones exposées."}],"explanation":"Kératoses actiniques : précancéreuses cutanées les plus fréquentes, des zones photo-exposées, rugueuses, multiples ; potentiel de transformation limité (CE, pas CBC) ; marqueur de risque de cancer cutané.","src":"p. 357, 361"},{"id":"d302-qcm-104","type":"QRM","rank":"A","objective":"d302-obj-05","tags":["clinique","pièges"],"difficulty":2,"stem":"Un homme de 68 ans consulte pour une lésion de la tempe évocatrice de carcinome basocellulaire. Quelle(s) proposition(s) concernant le CBC est/sont exacte(s) ?","options":[{"t":"Il se développe le plus souvent sur une kératose actinique","ok":false,"why":"Il n'a pas de précurseur : les kératoses actiniques ne se transforment pas en CBC."},{"t":"Un bilan d'extension à distance (TEP, scanner) est systématique","ok":false,"why":"Les métastases sont exceptionnelles : il n'y a pas de bilan d'extension à distance."},{"t":"Il ne siège jamais sur les muqueuses","ok":true,"why":"Le CBC est exclusivement cutané, sur zones photo-exposées, alors que le CE peut être cutané ou muqueux."},{"t":"Il donne fréquemment des métastases ganglionnaires","ok":false,"why":"La malignité est locale : les métastases sont exceptionnelles."},{"t":"La forme sclérodermiforme est la plus fréquente","ok":false,"why":"La forme la plus fréquente est le CBC nodulaire ; la forme sclérodermiforme est une cicatrice blanchâtre, dure, mal limitée."}],"explanation":"CBC : cutané exclusivement (jamais sur les muqueuses), sans précurseur, évolution lente et locale, métastases exceptionnelles, pas de bilan d'extension à distance ; la perle est la clé sémiologique et la forme nodulaire la plus fréquente.","trap":"Ne pas transposer au CBC ce qui vaut pour le CE (précurseurs, atteinte muqueuse, métastases).","src":"p. 356, 361, 365"},{"id":"d302-qcm-105","type":"QRM","rank":"A","objective":"d302-obj-05","tags":["clinique","complications"],"difficulty":2,"stem":"À propos du carcinome épidermoïde cutané invasif, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Il ne métastase jamais","ok":false,"why":"Les métastases sont possibles : dissémination lymphophile puis hématogène."},{"t":"Son évolution est lente et purement locale","ok":false,"why":"Cela décrit le CBC ; le CE a une évolution agressive."},{"t":"Un bilan d'extension (scanner, TEP) est réalisé chez tous les patients","ok":false,"why":"Pas de bilan d'extension systématique, sauf forme agressive, terrain à risque (immunodépression) ou signe d'extension locorégionale."},{"t":"Il ne siège jamais sur les muqueuses","ok":false,"why":"Le CE peut être cutané ou muqueux, contrairement au CBC."},{"t":"Il survient souvent sur une lésion précancéreuse","ok":true,"why":"Le CE résulte très souvent de l'évolution d'un précurseur, même s'il peut survenir de novo."}],"explanation":"CE : précurseurs fréquents (kératose actinique, leucoplasie), localisation cutanée ou muqueuse, potentiel agressif et métastatique (voie lymphophile puis hématogène), bilan d'extension seulement dans les situations à risque.","src":"p. 356, 360, 365"},{"id":"d302-qcm-106","type":"QRM","rank":"A","objective":"d302-obj-05","tags":["paraclinique","diagnostic"],"difficulty":3,"stem":"Un homme de 74 ans, greffé rénal, présente une lésion ulcéro-bourgeonnante de la tempe, d'allure agressive. La biopsie confirme un carcinome épidermoïde. Quelles propositions sont exactes ?","options":[{"t":"On cherche d'autres carcinomes ou un mélanome sur l'ensemble de la peau","ok":true,"why":"L'examen cutané complet fait partie de l'examen clinique, car terrain et facteurs de risque sont communs aux carcinomes et au mélanome."},{"t":"La radiothérapie exclusive est le traitement de première intention, dès la confirmation","ok":false,"why":"Le traitement de première intention est l'exérèse chirurgicale avec marges ; la radiothérapie est une alternative pour les malades inopérables ou les localisations délabrantes."},{"t":"Un bilan d'extension (échographie ganglionnaire, scanner, TEP) est justifié","ok":true,"why":"Il est indiqué en cas de forme agressive ou de terrain à risque particulier comme l'immunodépression."},{"t":"Le dossier n'a pas à être discuté en RCP quel que soit le type de carcinome","ok":false,"why":"La discussion en RCP est la règle pour les carcinomes, sauf pour les CBC sans critère agressif."},{"t":"On recherche une adénopathie dans le territoire de drainage","ok":true,"why":"La palpation du territoire de drainage fait partie de l'examen clinique, avec le contrôle de la mobilité par rapport au plan profond et la mesure du diamètre."}],"explanation":"CEC chez un immunodéprimé : examen clinique complet (mobilité, diamètre, adénopathies, autres tumeurs cutanées), bilan d'extension justifié par le terrain et l'aspect agressif, prise en charge discutée en RCP et exérèse chirurgicale avec marges.","src":"p. 360, 363-364"},{"id":"d302-qcm-107","type":"QRM","rank":"A","objective":"d302-obj-04","tags":["traitement"],"difficulty":2,"stem":"À propos du traitement des carcinomes cutanés localisés, quelles propositions sont exactes ?","options":[{"t":"Tous les CBC, même sans aucun critère agressif, doivent être présentés systématiquement en RCP","ok":false,"why":"La discussion en RCP est la règle, sauf pour les CBC sans critères agressifs."},{"t":"Si l'exérèse est incomplète ou « limite », une reprise est indispensable","ok":true,"why":"L'examen anatomopathologique de la pièce juge du caractère complet de l'exérèse."},{"t":"Les marges d'exérèse sont plus larges pour le CBC que pour le carcinome épidermoïde","ok":false,"why":"C'est l'inverse : les marges sont plus élevées pour le CEC que pour le CBC."},{"t":"L'exérèse chirurgicale est le traitement de première intention","ok":true,"why":"Le traitement des formes localisées de CBC et de CE est généralement similaire : exérèse avec marges selon le groupe pronostique."},{"t":"Les marges standardisées vont de 3 à 10 mm selon le groupe pronostique","ok":true,"why":"La marge saine est mesurée autour de la tumeur."}],"explanation":"Exérèse chirurgicale en première intention, marges standardisées de 3 à 10 mm (plus élevées pour le CEC), reprise si exérèse incomplète ou limite, RCP sauf CBC sans critère agressif.","src":"p. 363-364"},{"id":"d302-qcm-108","type":"QRM","rank":"A","objective":"d302-obj-07","tags":["prévention"],"difficulty":1,"stem":"Quelles mesures relèvent de la prévention primaire des cancers cutanés ?","options":[{"t":"Déconseiller l'usage des lampes à bronzer","ok":true,"why":"Les UV artificiels doivent être évités."},{"t":"Utiliser un écran solaire de façon répétée pour pouvoir prolonger l'exposition au soleil","ok":false,"why":"L'écran solaire est utile ponctuellement contre le coup de soleil, mais il ne doit pas permettre d'augmenter le temps d'exposition."},{"t":"Cibler en priorité les sujets de phototype clair","ok":true,"why":"La prévention cible en priorité les phototypes clairs et les sujets aux multiples expositions solaires professionnelles ou récréatives."},{"t":"Éviter l'exposition solaire entre 12 h et 16 h","ok":true,"why":"C'est la stratégie d'évitement des heures de fort ensoleillement."},{"t":"Limiter les expositions solaires, surtout pendant l'enfance et l'adolescence","ok":true,"why":"Ces périodes sont à privilégier pour la prévention."}],"explanation":"Évitement solaire (12 h à 16 h, chapeau, vêtements, ombre), pas de lampes à bronzer, limitation de l'exposition dès l'enfance, ciblage des phototypes clairs ; l'écran solaire ne doit pas allonger le temps d'exposition.","trap":"L'écran solaire ne doit jamais servir à rester plus longtemps au soleil.","src":"p. 365"},{"id":"d302-qcm-109","type":"QRM","rank":"A","objective":"d302-obj-02","tags":["traitement","étiologie"],"difficulty":2,"stem":"À propos des infections cutanées à HPV (verrues), quelles propositions sont exactes ?","options":[{"t":"Le diagnostic positif repose sur une biopsie systématique","ok":false,"why":"Le diagnostic positif des infections à HPV repose sur la clinique."},{"t":"Il n'existe pas de traitement spécifique de l'infection à HPV","ok":true,"why":"L'objectif du traitement est la disparition des lésions macroscopiquement visibles."},{"t":"Un traitement agressif est recommandé pour éradiquer systématiquement les lésions","ok":false,"why":"Compte tenu de la régression spontanée fréquente, les traitements agressifs ne sont pas recommandés."},{"t":"La régression des verrues est le plus souvent spontanée","ok":true,"why":"D'où l'absence d'acharnement thérapeutique : le traitement est guidé par les symptômes et le vécu de la maladie."},{"t":"Les lésions cutanées à HPV se cancérisent le plus souvent sans aucun co-carcinogène","ok":false,"why":"Pour les lésions cutanées, des co-carcinogènes sont le plus souvent nécessaires : UV (+++), tabac, immunosuppression."}],"explanation":"Pas de traitement spécifique de l'HPV, régression le plus souvent spontanée, diagnostic clinique, pas d'acharnement thérapeutique ; la cancérisation des lésions cutanées nécessite le plus souvent des co-carcinogènes.","src":"p. 367, 370-371"},{"id":"d302-qcm-110","type":"QRM","rank":"A","objective":"d302-obj-02","tags":["traitement"],"difficulty":2,"stem":"Concernant les traitements des verrues, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Le laser CO2 se fait sans anesthésie, ne laisse jamais de cicatrice et ne récidive pas","ok":false,"why":"Il nécessite une anesthésie locale, peut laisser une cicatrice, et la récidive reste possible."},{"t":"Chez l'enfant, une éradication agressive et systématique est la règle","ok":false,"why":"Chez l'enfant, le traitement ne doit pas être agressif ; l'éradication systématique n'est pas toujours justifiée."},{"t":"L'acide salicylique s'applique sans protéger la peau saine périphérique","ok":false,"why":"Il faut protéger la peau saine périphérique (ou limiter le collodion salicylé à la surface de la verrue) et décaper mécaniquement au préalable."},{"t":"La cryothérapie est douloureuse sur les verrues péri- et sous-unguéales","ok":true,"why":"Elle est aussi douloureuse sur les verrues palmaires."},{"t":"Il existe un traitement préventif vrai des verrues","ok":false,"why":"Il n'existe pas de traitement préventif vrai : on limite la diffusion (vernis incolore les jours de piscine, hygiène familiale)."}],"explanation":"Kératolytiques (acide salicylique) : simples et indolores, avec décapage préalable et observance régulière ; cryothérapie : douloureuse en zones palmaires et unguéales ; laser CO2 : anesthésie locale, cicatrice possible, récidive possible ; chez l'enfant, pas d'agressivité.","src":"p. 370-371"},{"id":"d302-qcm-111","type":"QRM","rank":"A","objective":"d302-obj-11","tags":["clinique","diagnostic"],"difficulty":2,"stem":"À propos de la suspicion clinique de mélanome, quelles propositions sont exactes ?","options":[{"t":"Le critère de diamètre supérieur à 6 mm est non spécifique","ok":true,"why":"Le D de la règle ABCDE est signalé comme critère non spécifique."},{"t":"Le prurit et le saignement au contact sont des signes précoces qui doivent faire suspecter un mélanome","ok":false,"why":"Ce sont des signes tardifs."},{"t":"La règle ABCDE fait suspecter un mélanome à partir de 2 critères","ok":true,"why":"Suspicion si au moins 2 critères parmi asymétrie, bords irréguliers, couleur inhomogène, diamètre, évolution."},{"t":"Le « vilain petit canard » est un nævus discordant par rapport aux autres du patient","ok":true,"why":"Elle nécessite un examen corps entier, patient dénudé."},{"t":"La règle ABCDE repère mal les modifications subtiles ou récentes","ok":true,"why":"Initialement conçue pour l'éducation du patient à l'autodépistage, elle repère mal ces modifications."}],"explanation":"La suspicion repose sur deux éléments : la règle analytique ABCDE (au moins 2 critères) et la règle cognitive du « vilain petit canard » ; prurit et saignement sont tardifs.","src":"p. 374"},{"id":"d302-qcm-112","type":"QRM","rank":"A","objective":"d302-obj-11","tags":["diagnostic","traitement"],"difficulty":2,"stem":"Une femme de 52 ans présente une lésion pigmentée du dos, asymétrique, à bords irréguliers, de couleur inhomogène, apparue depuis trois mois. Quelles propositions concernant l'exérèse diagnostique sont exactes ?","options":[{"t":"Un long délai de réflexion est indispensable avant l'exérèse","ok":false,"why":"Il existe une notion d'urgence diagnostique : le délai de réflexion n'est pas rigoureusement indispensable."},{"t":"Elle emporte la tumeur en entier, jusqu'à l'hypoderme","ok":true,"why":"L'exérèse doit être complète pour permettre la mesure du Breslow et de l'index mitotique."},{"t":"Une biopsie partielle de la zone la plus pigmentée est préférable","ok":false,"why":"La mesure précise de l'épaisseur (Breslow) et de l'index mitotique est impossible sur un prélèvement partiel, ce qui entraîne une perte de chance."},{"t":"L'examen anatomopathologique est inutile si la dermoscopie est typique","ok":false,"why":"La dermoscopie est utile mais non obligatoire ; l'examen anatomopathologique est obligatoire chaque fois qu'on excise une lésion."},{"t":"Elle se fait sous anesthésie locale","ok":true,"why":"Modalités de l'exérèse : information du patient, anesthésie locale, exérèse complète."}],"explanation":"Lésion suspecte de mélanome : exérèse rapide à visée diagnostique, sous anesthésie locale, complète jusqu'à l'hypoderme, suivie d'un examen anatomopathologique obligatoire.","trap":"Pas de biopsie partielle (sauf lésion très étendue dont l'exérèse totale serait délabrante, après avis d'un centre expert).","src":"p. 373-375"},{"id":"d302-qcm-113","type":"QRM","rank":"A","objective":"d302-obj-12","tags":["complications"],"difficulty":2,"stem":"Concernant l'évolution du mélanome, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Le cerveau n'est jamais une localisation métastatique du mélanome","ok":false,"why":"Les métastases à distance peuvent toucher n'importe quel organe, avec un risque particulier pour le cerveau."},{"t":"À indice de Breslow identique, le pronostic diffère nettement selon la forme anatomoclinique","ok":false,"why":"À Breslow identique, toutes les formes anatomocliniques ont un pronostic globalement comparable."},{"t":"Un mélanome invasif ne récidive jamais après exérèse complète","ok":false,"why":"Un risque plus ou moins élevé de récidive existe dans tous les cas, même de façon retardée."},{"t":"Un mélanome in situ guérit de façon constante après exérèse élargie","ok":true,"why":"Le mélanome in situ est confiné à l'épiderme : la guérison est constante après exérèse et marge élargie."},{"t":"Les métastases à distance surviennent toujours avant les métastases ganglionnaires régionales","ok":false,"why":"Elles surviennent souvent, mais pas exclusivement, après les métastases ganglionnaires régionales."}],"explanation":"Mélanome in situ : guérison constante après exérèse élargie. Mélanome invasif : risque de récidive locale, en transit, ganglionnaire ou à distance (cerveau), même tardif. À Breslow identique, pronostic comparable entre formes anatomocliniques.","src":"p. 375, 377-378"},{"id":"d302-qcm-114","type":"QRM","rank":"A","objective":"d302-obj-04","tags":["traitement"],"difficulty":2,"stem":"Quelle(s) proposition(s) concernant le traitement de la tumeur primitive d'un mélanome est/sont exacte(s) ?","options":[{"t":"Une radiothérapie complémentaire systématique est recommandée après l'exérèse élargie","ok":false,"why":"Au stade de tumeur primitive isolée, la radiothérapie et la chimiothérapie ne sont jamais indiquées."},{"t":"Une chimiothérapie adjuvante est systématique après exérèse de la tumeur primitive","ok":false,"why":"Au stade de tumeur primitive isolée, la radiothérapie et la chimiothérapie ne sont jamais indiquées."},{"t":"La chirurgie de Mohs est la technique standard pour tout mélanome","ok":false,"why":"Elle n'est citée que pour le mélanome de Dubreuilh intra-épidermique, mal limité et très récidivant, comme alternative à une marge de 1 cm."},{"t":"Les marges sont identiques quelle que soit l'épaisseur tumorale","ok":false,"why":"Elles augmentent avec le Breslow : in situ 0,5 cm, 0,1 à 1 mm 1 cm, 1,1 à 2 mm 1 à 2 cm, supérieur à 2 mm 2 cm."},{"t":"Une exérèse élargie jusqu'au fascia est recommandée, selon le Breslow","ok":true,"why":"La profondeur va jusqu'au fascia, en le respectant ; les marges dépendent essentiellement du Breslow."}],"explanation":"Après l'exérèse diagnostique, exérèse élargie complémentaire jusqu'au fascia, avec marges selon le Breslow ; pas de radiothérapie ni de chimiothérapie au stade de tumeur primitive isolée.","src":"p. 380"},{"id":"d302-qcm-115","type":"QRM","rank":"B","objective":"d302-obj-12","tags":["complications"],"difficulty":2,"stem":"Parmi les propositions suivantes, lesquelles sont des facteurs pronostiques d'un mélanome au stade de tumeur primitive ?","options":[{"t":"Le nombre de nævus du patient","ok":false,"why":"C'est un marqueur de risque de survenue du mélanome, pas un critère pronostique histologique de la tumeur."},{"t":"L'ulcération","ok":true,"why":"Elle a une valeur péjorative importante quelle que soit l'épaisseur de la tumeur."},{"t":"Le sous-type anatomoclinique, à indice de Breslow identique","ok":false,"why":"À Breslow identique, les différentes formes anatomocliniques ont un pronostic globalement comparable."},{"t":"L'indice de Breslow","ok":true,"why":"C'est le principal critère pronostique, avec une corrélation presque linéaire avec la mortalité."},{"t":"La localisation sur une zone photo-exposée","ok":false,"why":"Les principaux facteurs pronostiques liés à la tumeur primaire sont histologiques (Breslow, ulcération, index mitotique)."}],"explanation":"Un diagnostic précoce et une exérèse correcte sont les clés du pronostic ; les facteurs pronostiques de la tumeur primitive sont surtout histologiques : Breslow (principal), ulcération, index mitotique.","src":"p. 375, 378"},{"id":"d302-qcm-116","type":"QRM","rank":"A","objective":"d302-obj-08","tags":["étiologie","pièges"],"difficulty":2,"stem":"Concernant le risque de transformation des nævus communs en mélanome, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Les nævus du visage soumis au rasage ont un risque de transformation plus élevé","ok":false,"why":"Ni les nævus des zones de friction ni ceux du visage soumis au rasage n'ont un risque de transformation plus élevé."},{"t":"Les microtraumatismes répétés favorisent la transformation maligne","ok":false,"why":"Les microtraumatismes répétés n'induisent pas la transformation des nævus."},{"t":"La plupart des nævus restent stables","ok":true,"why":"La transformation est possible mais rare (probabilité inférieure à 1 pour 100 000) ; 80 % des mélanomes surviennent en dehors de toute lésion préexistante."},{"t":"Les nævus directement exposés au soleil ont un potentiel de dégénérescence plus élevé","ok":false,"why":"Les nævus du tronc ou du visage exposés au soleil n'ont pas un potentiel de dégénérescence plus élevé."},{"t":"Une exérèse préventive systématique de tous les nævus est recommandée","ok":false,"why":"Aucun intérêt à l'exérèse systématique préventive de tous les nævus pour prévenir un mélanome."}],"explanation":"Les nævus communs se transforment rarement ; 80 % des mélanomes naissent en dehors de toute lésion préexistante. Traumatismes, friction, rasage et exposition solaire du nævus lui-même n'augmentent pas le risque de transformation.","trap":"Un nævus qui s'irrite ou se traumatise ne devient pas pour autant un mélanome ; l'exérèse éventuelle est alors une question de confort.","src":"p. 388, 390"},{"id":"d302-qcm-117","type":"QRM","rank":"A","objective":"d302-obj-08","tags":["clinique"],"difficulty":2,"stem":"Quelles associations entre une lésion pigmentée et sa description sont exactes ?","options":[{"t":"Halo nævus de Sutton : halo érythémateux qui n'entraîne aucune modification du nævus","ok":false,"why":"Le halo est achromique (blanc) et aboutit à la disparition progressive du nævus."},{"t":"Nævus d'Ota : lésion unilatérale du territoire du trijumeau","ok":true,"why":"La sclérotique et la conjonctive homolatérale peuvent être pigmentées."},{"t":"Nævus bleu : tumeur maligne dermique à forte charge en mélanine, de pronostic réservé","ok":false,"why":"C'est une lésion bénigne, de localisation dermique, riche en mélanine, d'aspect bleuté."},{"t":"Nævus cliniquement atypique : nævus de type dermique pur","ok":false,"why":"Les nævus cliniquement atypiques sont de type jonctionnel."},{"t":"Tache bleue mongolique : tache ardoisée lombo-sacrée du nourrisson, régressive","ok":true,"why":"Elle s'apparente à un nævus bleu congénital, d'environ 10 cm de diamètre."}],"explanation":"Tache bleue mongolique (lombo-sacrée, régressive), nævus d'Ota (trijumeau, unilatéral), halo nævus de Sutton (halo achromique, disparition du nævus), nævus bleu (bénin, dermique), nævus cliniquement atypique (jonctionnel).","src":"p. 384, 386-387"},{"id":"d302-qcm-118","type":"QRM","rank":"B","objective":"d302-obj-08","tags":["prévention","pièges"],"difficulty":2,"stem":"Concernant la prise en charge des nævus, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Tous les nævus doivent être excisés de façon préventive","ok":false,"why":"Aucun intérêt à l'exérèse systématique préventive de tous les nævus."},{"t":"Un nævus excisé dont l'aspect paraît bénin se passe d'examen histologique","ok":false,"why":"L'examen histologique est obligatoire pour toute pièce d'exérèse."},{"t":"Les nævus cliniquement atypiques justifient une exérèse préventive systématique","ok":false,"why":"Ce sont un marqueur phénotypique de risque ; l'exérèse préventive n'est pas justifiée."},{"t":"Tous les individus doivent avoir une surveillance médicale régulière de leurs nævus","ok":false,"why":"Il n'y a pas lieu de surveiller médicalement tous les individus ; en revanche l'autosurveillance doit être enseignée à tous."},{"t":"L'exérèse d'un nævus ne provoque pas sa transformation en mélanome","ok":true,"why":"C'est une idée reçue à combattre ; l'exérèse d'une lésion pigmentée suspecte ne doit jamais être différée."}],"explanation":"Pas d'exérèse préventive systématique des nævus, examen histologique obligatoire de toute pièce, autosurveillance enseignée à tous, surveillance médicale réservée aux sujets à risque.","src":"p. 386, 389-391"},{"id":"d302-qru-101","type":"QRU","rank":"A","objective":"d302-obj-05","tags":["clinique","diagnostic"],"difficulty":1,"stem":"Un agriculteur de 74 ans présente depuis des mois des lésions multiples du dos des mains et du visage, érythémateuses, croûteuses, rugueuses comme du papier de verre, qui saignent facilement après grattage. Quel est le diagnostic le plus probable ?","options":[{"t":"Carcinome basocellulaire superficiel","ok":false,"why":"Il forme une plaque érythémateuse et squameuse bordée de petites perles, surtout sur le tronc."},{"t":"Verrues vulgaires","ok":false,"why":"Ce sont des élevures de 3 à 4 mm à surface hérissée de saillies villeuses kératosiques grisâtres."},{"t":"Kératoses actiniques","ok":true,"why":"Lésions kératosiques ou croûteuses multiples, rugueuses « papier de verre », des zones photo-exposées : description typique."},{"t":"Kératoses séborrhéiques","ok":false,"why":"Lésions bénignes du tronc, à surface grasse ou cérébriforme et à bords rectilignes."},{"t":"Mélanome superficiel extensif","ok":false,"why":"Il s'agit d'une lésion pigmentée évoquée sur les critères ABCDE ; ce tableau multiple, kératosique et croûteux n'en est pas un."}],"explanation":"Les kératoses actiniques sont des lésions kératosiques ou croûteuses multiples, rugueuses, des zones photo-exposées (visage, dos des mains), précancéreuses du CE.","src":"p. 354, 357, 368, 389"},{"id":"d302-qru-102","type":"QRU","rank":"A","objective":"d302-obj-05","tags":["paraclinique","pièges"],"difficulty":2,"stem":"Un homme de 66 ans a un carcinome basocellulaire nodulaire de l'aile du nez, confirmé par l'examen anatomopathologique. Quelle attitude est recommandée pour le bilan d'extension à distance ?","options":[{"t":"Échographie ganglionnaire systématique de la zone de drainage","ok":false,"why":"Elle n'est envisagée que pour les CEC à risque ; il n'y a pas de bilan d'extension pour le CBC."},{"t":"Scanner thoraco-abdominal systématique avant tout traitement","ok":false,"why":"Comme la TEP, il n'est envisagé que pour un CEC à risque ; pas de bilan d'extension pour le CBC."},{"t":"TEP-scan systématique avant l'exérèse","ok":false,"why":"Il n'est envisagé que pour un CEC à risque (forme agressive, immunodépression, extension locorégionale)."},{"t":"IRM du massif facial systématique avant l'exérèse","ok":false,"why":"Une imagerie locale (scanner cranio-facial, IRM du massif facial) est parfois nécessaire dans les formes étendues pour guider le traitement, mais elle n'est pas systématique."},{"t":"Aucun bilan d'extension à distance systématique","ok":true,"why":"Le CBC métastase exceptionnellement ; seul l'examen clinique est systématique, à la recherche d'autres carcinomes associés."}],"explanation":"CBC : pas de bilan d'extension à distance (métastases exceptionnelles). Le bilan d'extension (échographie ganglionnaire, scanner, TEP) concerne seulement les CEC à risque.","src":"p. 363, 365-366"},{"id":"d302-qru-103","type":"QRU","rank":"A","objective":"d302-obj-11","tags":["diagnostic","traitement"],"difficulty":1,"stem":"Une femme de 45 ans consulte pour un nævus du dos dont la forme et la couleur ont changé depuis trois mois : asymétrie, bords irréguliers, couleur inhomogène. Quelle est la conduite à tenir ?","options":[{"t":"Biopsie partielle de la zone la plus foncée","ok":false,"why":"La mesure précise du Breslow et de l'index mitotique est impossible sur un prélèvement partiel : perte de chance pour le patient."},{"t":"Exérèse complète à visée diagnostique avec examen anatomopathologique","ok":true,"why":"Lésion suspecte de mélanome : exérèse rapide et complète, avec analyse histologique de la pièce entière."},{"t":"Cryothérapie par azote liquide","ok":false,"why":"Détruire la lésion ne permet ni confirmation anatomopathologique ni analyse des critères histopronostiques."},{"t":"Surveillance dermoscopique rapprochée sans prélèvement","ok":false,"why":"Une lésion suspecte relève d'une exérèse rapide (notion d'urgence diagnostique) ; la dermoscopie est utile mais non obligatoire."},{"t":"Exérèse élargie d'emblée avec une marge de 2 cm, sans examen histologique","ok":false,"why":"L'examen anatomopathologique est obligatoire chaque fois qu'on excise une lésion ; il oriente les marges de l'éventuelle reprise (Breslow)."}],"explanation":"Devant une lésion pigmentée suspecte (ABCDE), on réalise une exérèse complète à visée diagnostique, puis l'examen anatomopathologique confirme et précise le Breslow, l'ulcération et l'index mitotique.","src":"p. 373-375"},{"id":"d302-qru-104","type":"QRU","rank":"A","objective":"d302-obj-04","tags":["traitement"],"difficulty":2,"stem":"Après exérèse diagnostique, l'examen anatomopathologique conclut à un mélanome d'indice de Breslow égal à 3 mm. Quelle marge chirurgicale élargie est conseillée ?","options":[{"t":"0,5 cm","ok":false,"why":"C'est la marge d'un mélanome intra-épidermique (in situ)."},{"t":"1 cm","ok":false,"why":"C'est la marge d'un mélanome de Breslow compris entre 0,1 et 1 mm."},{"t":"1 à 2 cm","ok":false,"why":"C'est la marge d'un mélanome de Breslow compris entre 1,1 et 2 mm."},{"t":"2 cm","ok":true,"why":"Pour un Breslow supérieur à 2 mm, la marge conseillée est de 2 cm, jusqu'au fascia."},{"t":"Aucune reprise n'est nécessaire","ok":false,"why":"Une exérèse élargie complémentaire est recommandée, avec des marges selon le Breslow."}],"explanation":"Marges conseillées (recommandations 2016) : in situ 0,5 cm ; 0,1 à 1 mm : 1 cm ; 1,1 à 2 mm : 1 à 2 cm ; supérieur à 2 mm : 2 cm.","src":"p. 380"},{"id":"d302-qru-105","type":"QRU","rank":"A","objective":"d302-obj-02","tags":["clinique","diagnostic"],"difficulty":1,"stem":"Un adolescent consulte pour une lésion plantaire unique, douloureuse à la pression, entourée d'un épais anneau kératosique et piquetée de points noirs. Quel est le diagnostic ?","options":[{"t":"Myrmécie (HPV1)","ok":true,"why":"Verrue plantaire profonde, la plus fréquente, douloureuse à la pression, piquetée de points noirs (microhémorragies)."},{"t":"Verrues en mosaïque (HPV2)","ok":false,"why":"Elles sont non douloureuses, faites de multiples verrues coalescentes en placard kératosique moins épais."},{"t":"Durillon","ok":false,"why":"Simple épaississement cutané lié à un frottement chronique sur les points d'appui : diagnostic différentiel."},{"t":"Mélanome achromique","ok":false,"why":"Diagnostic différentiel à ne pas manquer à la plante des pieds, mais le tableau décrit est celui d'une verrue."},{"t":"Verrue plane (HPV3)","ok":false,"why":"Petites papules très peu en relief du visage, du dos des mains et des membres."}],"explanation":"La myrmécie (HPV1) est la verrue plantaire la plus fréquente : profonde, douloureuse à la pression, avec anneau kératosique et points noirs.","src":"p. 368-370"},{"id":"d302-qru-106","type":"QRU","rank":"A","objective":"d302-obj-05","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Un homme de 68 ans consulte pour une lésion du gland, érythémateuse rouge vif, bien limitée, discrètement érosive, évoluant depuis des mois. Quel est le diagnostic le plus probable ?","options":[{"t":"Leucoplasie","ok":false,"why":"La leucoplasie est blanchâtre, adhérente, asymptomatique et ne saigne pas au contact."},{"t":"Carcinome basocellulaire","ok":false,"why":"Le CBC ne siège jamais sur les muqueuses."},{"t":"Érythroplasie de Queyrat","ok":true,"why":"Forme masculine du carcinome in situ de la muqueuse génitale ; la biopsie avec examen anatomopathologique confirme le diagnostic."},{"t":"Kératose actinique","ok":false,"why":"Lésion kératosique des zones cutanées photo-exposées (visage, dos des mains)."},{"t":"Carcinome épidermoïde invasif ulcéro-bourgeonnant","ok":false,"why":"Une infiltration, avec ou sans ulcération franche, ferait évoquer une forme invasive ; ici la lésion est bien limitée et discrètement érosive."}],"explanation":"L'érythroplasie de Queyrat est le carcinome in situ du gland : lésion rouge vif, bien limitée, parfois discrètement érosive ; biopsie pour confirmer, traitements locaux chirurgicaux ou destructeurs.","src":"p. 357-358, 361"},{"id":"d302-qru-107","type":"QRU","rank":"B","objective":"d302-obj-12","tags":["diagnostic"],"difficulty":2,"stem":"Une femme de 78 ans présente sur la joue une plaque pigmentée mal limitée, d'extension lente depuis plusieurs années, sur une peau photovieillie. Quel mélanome évoquer ?","options":[{"t":"Mélanome nodulaire","ok":false,"why":"Il n'a pas de phase d'extension horizontale initiale : il est d'emblée vertical et rapidement invasif."},{"t":"Mélanome de Dubreuilh","ok":true,"why":"Il siège sur les zones chroniquement photo-exposées, surtout le visage des sujets de plus de 60 ans, avec une longue évolution horizontale."},{"t":"Mélanome acral lentigineux","ok":false,"why":"Il siège sur les paumes, les plantes, les bords latéraux des doigts et l'appareil unguéal."},{"t":"Mélanome superficiel extensif","ok":false,"why":"C'est la forme la plus fréquente (60 à 70 %), liée aux expositions intermittentes et intenses, pas à l'exposition chronique cumulative."},{"t":"Mélanome des muqueuses","ok":false,"why":"Il siège sur les muqueuses buccales ou génitales."}],"explanation":"Mélanome de Dubreuilh : visage, sujets de plus de 60 ans, exposition chronique cumulative, signes de photovieillissement, longue phase horizontale avant des nodules à croissance verticale.","src":"p. 372, 375"},{"id":"d302-qru-108","type":"QRU","rank":"A","objective":"d302-obj-08","tags":["grossesse","pièges"],"difficulty":2,"stem":"Une femme enceinte de 30 ans consulte pour un nævus abdominal dont la taille et la pigmentation ont augmenté, avec un aspect qui fait douter. Quelle est la conduite recommandée ?","options":[{"t":"Abstention : ces modifications sont toujours physiologiques pendant la grossesse","ok":false,"why":"Augmentation de taille et modification de pigmentation sont possibles pendant la grossesse, mais la vigilance s'impose (formes agressives de mélanome)."},{"t":"Surveillance simple jusqu'à l'accouchement","ok":false,"why":"En cas de doute, la conduite recommandée est l'exérèse."},{"t":"Cryothérapie de la lésion","ok":false,"why":"Détruire sans prélèvement exclut toute analyse anatomopathologique."},{"t":"Exérèse avec examen anatomopathologique","ok":true,"why":"En cas de doute, l'exérèse s'impose : la grossesse peut modifier les nævus mais des formes agressives de mélanome sont possibles."},{"t":"Biopsie partielle de la zone la plus pigmentée","ok":false,"why":"Une lésion suspecte relève d'une exérèse complète : la biopsie partielle ne permet pas de mesurer précisément le Breslow."}],"explanation":"Pendant la grossesse, les nævus peuvent grossir (abdomen ++) et se pigmenter ; des formes agressives de mélanome sont possibles (immuno-modulation) : en cas de doute, exérèse.","src":"p. 384"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"d302-pareto","points":[{"id":"d302-par-01","rank":"A","cat":"clinique","text":"Mélanome suspect (règle **ABCDE** ≥ 2 critères, **vilain petit canard**) → **exérèse complète** à visée diagnostique, jamais de biopsie partielle ; anatomopathologie obligatoire","src":"p. 374-375"},{"id":"d302-par-02","rank":"A","cat":"traitement","text":"Marges d'exérèse du mélanome : in situ **0,5 cm** ; Breslow 0,1-1 mm **1 cm** ; 1,1-2 mm **1 à 2 cm** ; supérieur à 2 mm **2 cm** ; jusqu'au fascia ; radiothérapie et chimiothérapie jamais indiquées","src":"p. 380"},{"id":"d302-par-03","rank":"A","cat":"gravité","text":"**Breslow** (épaisseur maximale, mesurée sur la pièce entière) puis **ulcération** = facteurs pronostiques du mélanome ; à Breslow égal, toutes les formes anatomocliniques ont un pronostic comparable","src":"p. 374-375, 378"},{"id":"d302-par-04","rank":"A","cat":"piège","text":"**CBC** : jamais sur les muqueuses, **sans précurseur**, métastases exceptionnelles, pas de bilan d'extension ; **CE** : précurseurs fréquents, cutané ou muqueux, métastases possibles (lymphophiles puis hématogènes)","src":"p. 356, 361, 365"},{"id":"d302-par-05","rank":"A","cat":"clinique","text":"**CBC** = cancer cutané le plus fréquent : clé sémiologique = **perle** (papule rosée translucide télangiectasique) ; formes nodulaire (+ fréquente), superficiel (tronc), **sclérodermiforme** (cicatrice dure)","src":"p. 361, 365"},{"id":"d302-par-06","rank":"A","cat":"clinique","text":"**CEC** invasif (surtout après 60 ans, zone photo-exposée) : **ulcération + bourgeonnement + croûte** ; bilan d'extension seulement si forme agressive, immunodépression ou signe locorégional","src":"p. 358-360"},{"id":"d302-par-07","rank":"A","cat":"étiologie","text":"Précurseurs du CE : **kératose actinique** (la plus fréquente, « papier de verre »), **leucoplasie** (muqueuse), **maladie de Bowen** = CE in situ (Queyrat au gland) ; invasion = infiltration ± ulcération","src":"p. 357-358"},{"id":"d302-par-08","rank":"A","cat":"traitement","text":"Carcinomes localisés : **exérèse chirurgicale** avec marges de 3 à 10 mm (plus larges pour le CE), **reprise** si exérèse incomplète ; RCP sauf CBC non agressif ; suivi régulier, au mieux à vie","src":"p. 363-364, 366"},{"id":"d302-par-09","rank":"A","cat":"prévention","text":"Prévention solaire : éviter **12 h-16 h**, chapeau et vêtements, **pas de lampes à bronzer**, enfants et phototypes clairs en priorité ; l'écran solaire ne doit **pas allonger** l'exposition","src":"p. 365"},{"id":"d302-par-10","rank":"A","cat":"étiologie","text":"UV = carcinogène principal (latence **30-40 ans**) ; **CE** : exposition chronique cumulée ; **mélanome** : intense et intermittente (coups de soleil) ; autres FDR : phototype I-II, immunodépression, XP","src":"p. 355-356"},{"id":"d302-par-11","rank":"A","cat":"traitement","text":"**Verrues (HPV)** : diagnostic clinique, **pas de traitement spécifique**, régression le plus souvent spontanée, récidive d'environ **30 %** ; acide salicylique ou cryothérapie ; pas d'acharnement thérapeutique","src":"p. 370-371"},{"id":"d302-par-12","rank":"A","cat":"piège","text":"Verrue plantaire **myrmécie** (HPV1) : profonde, douloureuse, points noirs ; verrue péri-unguéale persistante → **carcinome in situ** ; lésion plantaire achromique → **mélanome achromique**","src":"p. 368-370"},{"id":"d302-par-13","rank":"A","cat":"étiologie","text":"**Nævus** commun : transformation rare (**80 %** des mélanomes sans lésion préexistante) ; marqueurs de risque : **plus de 50 nævus**, grande taille, nævus atypiques, antécédents familiaux de mélanome","src":"p. 388"},{"id":"d302-par-14","rank":"A","cat":"suivi","text":"Sujets à très haut risque de mélanome (antécédent, **syndrome des nævus atypiques**) : suivi spécifique, au moins **annuel à vie** + autosurveillance ; près de **80 %** des mélanomes sont repérés par le patient","src":"p. 374, 382, 391"},{"id":"d302-par-15","rank":"B","cat":"clinique","text":"Formes de mélanome : **SSM** le plus fréquent (60-70 %), **Dubreuilh** (visage, plus de 60 ans), **acral lentigineux** (paumes, plantes, ongles), **nodulaire** (sans phase horizontale)","src":"p. 375"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
